import './styles.css';
import { pagePalette, paletteSwatches } from './config/palette';
import { renderConfig } from './config/scene';
import type { RenderMode } from './config/scene';
import { createScene } from './scene/createScene';
import { createRenderer } from './rendering/createRenderer';
import { createAnimationController } from './animation/createAnimationController';
import type { AnimationState } from './animation/createAnimationController';
import { waterConfig } from './config/water';
import { resolveVisualOptions } from './config/visual';
import { resolveEnvironmentOptions } from './config/environment';

for (const [name, color] of Object.entries(pagePalette)) {
  document.documentElement.style.setProperty(`--color-${name}`, color);
}

const app = document.querySelector<HTMLDivElement>('#app');
if (!app) throw new Error('Missing application root.');

app.innerHTML = `
  <main class="study">
    <header class="masthead">
      <div class="identity">
        <svg class="mark" viewBox="0 0 32 32" fill="none" aria-hidden="true">
          <path d="m16 3 12 7v13l-12 7-12-7V10Z M4 10l12 7 12-7 M16 17v13" />
        </svg>
        <div>
          <h1>庭院习作</h1>
          <p class="eyebrow">A STUDY OF LIGHT & COLOR</p>
        </div>
      </div>
      <span class="view-label">固定视角<span aria-hidden="true"> ↗</span></span>
    </header>

    <figure class="composition" aria-label="光与颜色的场景习作">
      <div class="scene-host" id="scene-host" data-render-state="loading"></div>
      <figcaption class="scene-caption">
        <span>一方水池，几段旧时光。</span>
        <span class="caption-note">庭院的轮廓</span>
      </figcaption>
    </figure>

    <section class="tools" aria-label="画面显示设置">
      <p class="tools-label">观看方式</p>
      <div class="tool-actions">
        <div class="mode-controls" role="group" aria-label="渲染模式">
          <button type="button" data-mode="native" aria-pressed="true">正常画面</button>
          <button type="button" data-mode="pixel" aria-pressed="false">像素预览</button>
        </div>
        <button type="button" id="motion-control" class="motion-control">暂停动效</button>
      </div>
    </section>

    <footer class="palette-footer" aria-label="场景基础色板">
      <span class="palette-title">庭院色谱</span>
      <ul class="swatches"></ul>
    </footer>
    <p id="render-status" class="sr-only" role="status" aria-live="polite"></p>
  </main>
`;

const swatches = app.querySelector<HTMLUListElement>('.swatches')!;
for (const swatch of paletteSwatches) {
  const item = document.createElement('li');
  item.className = 'swatch';
  item.title = `${swatch.name} ${swatch.color}`;
  const chip = document.createElement('span');
  chip.className = 'swatch-chip';
  chip.style.backgroundColor = swatch.color;
  chip.setAttribute('aria-hidden', 'true');
  const label = document.createElement('span');
  label.textContent = swatch.name;
  item.append(chip, label);
  swatches.append(item);
}

const host = app.querySelector<HTMLDivElement>('#scene-host')!;
const status = app.querySelector<HTMLParagraphElement>('#render-status')!;
const buttons = [...app.querySelectorAll<HTMLButtonElement>('[data-mode]')];
const motionButton = app.querySelector<HTMLButtonElement>('#motion-control')!;
const query = new URLSearchParams(window.location.search);
const requestedMode = query.get('render');
let mode: RenderMode = requestedMode === 'pixel' || requestedMode === 'native'
  ? requestedMode
  : renderConfig.defaultMode;

const world = createScene(resolveEnvironmentOptions(query));
let view: ReturnType<typeof createRenderer> | undefined;
const listenerController = new AbortController();
const timeParameter = query.get('waterTime');
const parsedTime = timeParameter === null ? NaN : Number(timeParameter);
const fixedTime = Number.isFinite(parsedTime) && parsedTime >= 0 && parsedTime <= 86400 ? parsedTime : undefined;

function syncAnimation(state: AnimationState) {
  motionButton.textContent = state.playing ? '暂停动效' : '播放动效';
  motionButton.title = state.reducedMotion && !state.playing ? '已按减少动态设置暂停，点按可播放' : '';
  host.dataset.motionState = state.hidden ? 'hidden' : state.playing ? 'running' : 'paused';
  view?.setSuspended(state.hidden);
  view?.setAnimating(state.playing);
}
const animation = createAnimationController(syncAnimation, fixedTime ?? waterConfig.initialTime, fixedTime !== undefined);

function updateControls() {
  for (const button of buttons) {
    button.setAttribute('aria-pressed', String(button.dataset.mode === mode));
  }
  status.textContent = mode === 'pixel' ? '已切换为像素预览。' : '已切换为正常画面。';
}

try {
  view = createRenderer(host, mode, world.setAspect, resolveVisualOptions(query));
  view.start(world.scene, world.camera, (timestamp) => {
    const time = animation.advance(timestamp);
    world.update(time);
    host.dataset.waterTime = time.toFixed(6);
    host.dataset.sceneTime = time.toFixed(6);
  });
  syncAnimation(animation.state);
  updateControls();

  motionButton.addEventListener('click', () => {
    animation.toggle();
    status.textContent = animation.state.playing ? '场景动效已继续。' : '场景动效已暂停。';
  }, { signal: listenerController.signal });

  for (const button of buttons) {
    button.addEventListener('click', () => {
      mode = button.dataset.mode as RenderMode;
      view?.setMode(mode);
      const url = new URL(window.location.href);
      if (mode === renderConfig.defaultMode) url.searchParams.delete('render');
      else url.searchParams.set('render', mode);
      window.history.replaceState(null, '', url);
      updateControls();
    }, { signal: listenerController.signal });
  }
} catch (error) {
  view?.dispose();
  world.dispose();
  host.dataset.renderState = 'error';
  const message = document.createElement('p');
  message.className = 'render-error';
  message.textContent = '场景暂时无法显示，请开启浏览器图形加速后刷新页面。';
  host.replaceChildren(message);
  for (const button of buttons) button.disabled = true;
  motionButton.disabled = true;
  animation.dispose();
  status.textContent = '场景初始化失败。';
  console.error('Scene initialization failed.', error);
}

function dispose() {
  listenerController.abort();
  animation.dispose();
  view?.dispose();
  world.dispose();
}

if (import.meta.hot) {
  import.meta.hot.accept();
  import.meta.hot.dispose(dispose);
}

src/styles.css.content:
:root {
  font-family: "PingFang SC", "Microsoft YaHei", "Noto Sans CJK SC", sans-serif;
  color: var(--color-ink);
  background: var(--color-paper);
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
}

* { box-sizing: border-box; }
body { margin: 0; min-width: 280px; }
button { font: inherit; }

.study {
  width: min(100% - 48px, 680px);
  margin: 0 auto;
  padding: 34px 0 24px;
}

.masthead {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 24px;
}

.identity { display: flex; align-items: center; gap: 12px; }
.mark { width: 32px; height: 32px; stroke: currentColor; stroke-width: 1.2; }
h1 { margin: 0; font-size: 19px; font-weight: 500; letter-spacing: 0.18em; }
.eyebrow { margin: 5px 0 0; font-size: 8px; letter-spacing: 0.17em; color: var(--color-muted); }
.view-label { color: var(--color-muted); font-size: 11px; letter-spacing: 0.1em; white-space: nowrap; }
.view-label span { padding-left: 10px; }

.composition { margin: 0; }
.scene-host { position: relative; width: 100%; aspect-ratio: 1; overflow: hidden; }
.scene-host canvas { display: block; width: 100%; height: 100%; }
.scene-host canvas[data-render-mode="pixel"] { image-rendering: pixelated; }
.scene-caption {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  padding-top: 14px;
  color: var(--color-muted);
  font-size: 11px;
  line-height: 1.5;
  letter-spacing: 0.08em;
}
.caption-note { font-size: 10px; }

.tools { display: flex; justify-content: space-between; align-items: center; gap: 16px; padding: 25px 0; }
.tools-label { margin: 0; font-size: 11px; color: var(--color-muted); letter-spacing: 0.12em; }
.tool-actions { display: flex; align-items: center; gap: 10px; }
.motion-control {
  min-height: 42px; padding: 8px 13px; border: 1px solid var(--color-rule);
  border-radius: 7px; background: transparent; color: var(--color-ink);
  font-size: 11px; cursor: pointer; white-space: nowrap;
}
.motion-control:hover { background: var(--color-rule); }
.motion-control:focus-visible { outline: 2px solid var(--color-ink); outline-offset: 4px; }
.motion-control:disabled { cursor: default; opacity: 0.5; }
.mode-controls { display: flex; padding: 3px; border: 1px solid var(--color-rule); border-radius: 7px; gap: 2px; }
.mode-controls button {
  min-height: 36px;
  padding: 7px 16px;
  border: 0;
  border-radius: 4px;
  background: transparent;
  color: var(--color-muted);
  font-size: 11px;
  cursor: pointer;
  transition: background-color 150ms, color 150ms;
}
.mode-controls button[aria-pressed="true"] { background: var(--color-ink); color: var(--color-paper); }
.mode-controls button:hover:not([aria-pressed="true"]) { background: var(--color-rule); color: var(--color-ink); }
.mode-controls button:focus-visible { outline: 2px solid var(--color-ink); outline-offset: 4px; }
.mode-controls button:disabled { cursor: default; opacity: 0.5; }

.palette-footer { display: flex; align-items: center; gap: 24px; padding-top: 20px; border-top: 1px solid var(--color-rule); }
.palette-title { flex: 0 0 auto; font-size: 10px; color: var(--color-muted); letter-spacing: 0.12em; }
.swatches { display: flex; justify-content: space-between; flex: 1; flex-wrap: wrap; gap: 12px 20px; list-style: none; margin: 0; padding: 0; }
.swatch { display: flex; align-items: center; gap: 6px; font-size: 10px; color: var(--color-muted); white-space: nowrap; }
.swatch-chip { width: 13px; height: 13px; display: block; border: 1px solid color-mix(in srgb, var(--color-ink) 8%, transparent); border-radius: 3px; }
.render-error { display: grid; place-content: center; height: 100%; margin: 0; padding: 32px; text-align: center; font-size: 14px; line-height: 1.8; background: var(--color-rule); }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }

@media (min-width: 700px) and (min-height: 500px) {
  .study { width: min(100% - 64px, 680px, 100svh - 260px); }
}

@media (max-width: 520px) {
  .study { width: calc(100% - 32px); padding: 24px 0; }
  .masthead { margin-bottom: 20px; }
  h1 { font-size: 17px; }
  .eyebrow { font-size: 7px; letter-spacing: 0.12em; }
  .view-label { font-size: 10px; }
  .view-label span { padding-left: 4px; }
  .scene-caption { font-size: 10px; letter-spacing: 0.02em; }
  .caption-note { font-size: 9px; }
  .tools { padding: 22px 0; }
  .tools { display: block; }
  .tools-label { margin-bottom: 10px; }
  .tool-actions { justify-content: space-between; gap: 8px; }
  .motion-control { min-height: 44px; padding: 8px 10px; }
  .mode-controls button { min-height: 40px; padding: 8px 12px; }
  .palette-footer { display: block; padding-top: 18px; }
  .palette-title { display: block; margin-bottom: 13px; }
  .swatches { gap: 14px 12px; }
  .swatch { gap: 5px; font-size: 9px; }
  .swatch-chip { width: 12px; height: 12px; }
}

@media (prefers-reduced-motion: reduce) {
  .mode-controls button { transition: none; }
}

src/animation/createAnimationController..content:
import { waterConfig } from '../config/water';

/** Pure clock: clamps stalls, does not advance while paused, and can be tested without DOM. */
export function createAnimationClock(initialTime: number, maxDelta = waterConfig.maxFrameDelta) {
  let time = initialTime;
  let previous: number | null = null;
  return {
    get time() { return time; },
    resetTimestamp() { previous = null; },
    tick(timestamp: number, playing: boolean) {
      const delta = previous === null ? 0 : Math.min(maxDelta, Math.max(0, (timestamp - previous) / 1000));
      previous = timestamp;
      if (playing) time += delta;
      return time;
    },
  };
}

export interface AnimationState { playing: boolean; hidden: boolean; reducedMotion: boolean; }

export function createAnimationController(onChange: (state: AnimationState) => void, initialTime: number, initiallyPaused = false) {
  const media = window.matchMedia('(prefers-reduced-motion: reduce)');
  const clock = createAnimationClock(initialTime);
  let manualPaused: boolean | null = initiallyPaused ? true : null;
  let disposed = false;
  function state(): AnimationState {
    return { playing: !document.hidden && !(manualPaused ?? media.matches), hidden: document.hidden, reducedMotion: media.matches };
  }
  function notify() {
    if (disposed) return;
    clock.resetTimestamp();
    onChange(state());
  }
  function mediaChanged() {
    if (media.matches && manualPaused !== true) manualPaused = null;
    notify();
  }
  document.addEventListener('visibilitychange', notify);
  media.addEventListener('change', mediaChanged);
  return {
    get state() { return state(); },
    get time() { return clock.time; },
    advance(timestamp: number) { return clock.tick(timestamp, state().playing); },
    toggle() { manualPaused = !(manualPaused ?? media.matches); notify(); },
    dispose() {
      if (disposed) return;
      disposed = true;
      document.removeEventListener('visibilitychange', notify);
      media.removeEventListener('change', mediaChanged);
    },
  };
}

