/** Subtle environment motion; the seeded plant distribution is configured separately. */
export const environmentConfig = {
  seed: 82026,
  enabled: true,
  wind: {
    direction: [1, 0.32] as const,
    grassAngle: 8 * Math.PI / 180,
    flowerAngle: 6 * Math.PI / 180,
    gapAngle: 2.5 * Math.PI / 180,
    periods: [5.8, 4.4] as const,
    gustPeriod: 16,
  },
  canopy: { period: 10.5, secondaryPeriod: 12, displacement: 0.045, holeShade: 0.025 },
  petals: { enabled: false, capacity: 8, period: 11, lifetime: 6, drift: 0.16, minHeight: 0.07, maxHeight: 0.65 },
} as const;

export interface EnvironmentOptions {
  enabled: boolean;
  wind: boolean;
  canopy: boolean;
  petals: boolean;
}

export function resolveEnvironmentOptions(query: URLSearchParams): EnvironmentOptions {
  return {
    enabled: query.get('env') !== 'off' && environmentConfig.enabled,
    wind: query.get('wind') !== 'off',
    canopy: query.get('canopy') !== 'off',
    petals: query.get('petals') === 'on' || environmentConfig.petals.enabled,
  };
}

src/config/visual.ts.content:
export const pixelResolutions = [320, 384, 448] as const;
export type PixelResolution = typeof pixelResolutions[number];
export type FinishProfile = 'clean' | 'soft';

export interface PixelOptions {
  resolution: PixelResolution;
  finish: FinishProfile;
  storage: 'auto' | 'byte';
}

/** A fixed scene grid preserves world detail across viewport/DPR changes. */
export const visualConfig = {
  resolution: 384 as PixelResolution,
  finish: 'clean' as FinishProfile,
  finishes: {
    clean: { levels: 0, dither: 0 },
    soft: { levels: 64, dither: 0.18 },
  },
} as const;

/** Comparison controls live in URLs/configuration, not in the product toolbar. */
export function resolveVisualOptions(query: URLSearchParams): PixelOptions {
  const requested = Number(query.get('pixelSize'));
  return {
    resolution: pixelResolutions.some(size => size === requested) ? requested as PixelResolution : visualConfig.resolution,
    finish: query.get('finish') === 'soft' ? 'soft' : visualConfig.finish,
    storage: 'auto',
  };
}

src/geometry/createFlowerGeometry.ts.content:
import { BufferGeometry, Float32BufferAttribute } from 'three';

function plantGeometry(positions: number[], parts: number[], heights: number[]) {
  const geometry = new BufferGeometry();
  geometry.setAttribute('position', new Float32BufferAttribute(positions, 3));
  geometry.setAttribute('plantPart', new Float32BufferAttribute(parts, 1));
  geometry.setAttribute('plantHeight', new Float32BufferAttribute(heights, 1));
  geometry.computeVertexNormals();
  geometry.computeBoundingBox();
  geometry.computeBoundingSphere();
  return geometry;
}

type Point = readonly [number, number, number];
function builder() {
  const positions: number[] = [], parts: number[] = [], heights: number[] = [];
  function triangle(a: Point, b: Point, c: Point, part = 0) {
    for (const p of [a, b, c]) {
      positions.push(...p);
      parts.push(part);
      heights.push(p[1]);
    }
  }
  return { triangle, finish: () => plantGeometry(positions, parts, heights) };
}

export function createGrassGeometry() {
  const b = builder();
  for (let i = 0; i < 3; i++) {
    const angle = i * Math.PI * 2 / 3;
    const c = Math.cos(angle), s = Math.sin(angle);
    const height = i === 0 ? 1 : 0.72 + i * 0.08;
    const point = (x: number, y: number, z: number): Point => [c * x - s * z, y, s * x + c * z];
    const left = point(-0.12, 0, 0), right = point(0.12, 0, 0);
    const shoulder = point(0.08, height * 0.6, 0.10);
    const tip = point(0.23, height, 0.18);
    b.triangle(left, right, shoulder);
    b.triangle(left, shoulder, tip);
  }
  return b.finish();
}

export function createStemGeometry() {
  const b = builder();
  b.triangle([-0.025, 0, 0], [0.025, 0, 0], [0.025, 1, 0]);
  b.triangle([-0.025, 0, 0], [0.025, 1, 0], [-0.025, 1, 0]);
  b.triangle([0, 0, -0.025], [0, 0, 0.025], [0, 1, 0.025]);
  b.triangle([0, 0, -0.025], [0, 1, 0.025], [0, 1, -0.025]);
  b.triangle([0, 0.4, 0], [0.18, 0.65, 0.04], [0.04, 0.63, -0.04]);
  b.triangle([0, 0.56, 0], [-0.17, 0.77, -0.02], [-0.04, 0.76, 0.05]);
  return b.finish();
}

export function createFlowerGeometry(petals: 4 | 5) {
  const b = builder();
  for (let i = 0; i < petals; i++) {
    const angle = i * Math.PI * 2 / petals;
    const point = (radius: number, offset: number, y: number): Point => [Math.cos(angle + offset) * radius, y, Math.sin(angle + offset) * radius];
    const root = point(0.07, 0, 0), left = point(0.33, -0.48, 0.035);
    const tip = point(0.5, 0, 0.08), right = point(0.33, 0.48, 0.035);
    b.triangle(root, tip, left);
    b.triangle(root, right, tip);
  }
  const a: Point = [-0.085, 0.05, 0], c: Point = [0.085, 0.05, 0];
  b.triangle(a, [0, 0.05, 0.085], c, 1);
  b.triangle(a, c, [0, 0.05, -0.085], 1);
  return b.finish();
}

src/geometry/createStoneBlockGeometry.ts.content:
import { BufferGeometry, Float32BufferAttribute, Vector3 } from 'three';

type Point2 = readonly [number, number];
type Polygon = Vector3[];

export interface StoneGeometryOptions {
  bevel: number;
  cornerCut: number;
  seed: number;
  chipSize?: number;
  chipCorner?: number;
}

const EPSILON = 1e-7;

function distinct(points: Polygon): Polygon {
  const unique: Polygon = [];
  for (const p of points) {
    if (!unique.some(q => q.distanceToSquared(p) < EPSILON * EPSILON)) unique.push(p);
  }
  return unique;
}

/** Clip a closed convex solid, adding the new exposed face with outward winding. */
function clip(faces: Polygon[], normal: Vector3, distance: number): Polygon[] {
  const next: Polygon[] = [];
  const intersections: Polygon = [];
  for (const face of faces) {
    const polygon: Polygon = [];
    for (let i = 0; i < face.length; i++) {
      const a = face[i]!;
      const b = face[(i + 1) % face.length]!;
      const da = normal.dot(a) - distance;
      const db = normal.dot(b) - distance;
      if (da <= EPSILON) polygon.push(a);
      if ((da < -EPSILON && db > EPSILON) || (da > EPSILON && db < -EPSILON)) {
        const p = a.clone().lerp(b, da / (da - db));
        polygon.push(p);
        intersections.push(p);
      } else if (Math.abs(da) <= EPSILON) {
        intersections.push(a);
      }
    }
    const clean = distinct(polygon);
    if (clean.length >= 3) next.push(clean);
  }
  const cap = distinct(intersections);
  if (cap.length >= 3) {
    const center = cap.reduce((sum, p) => sum.add(p), new Vector3()).divideScalar(cap.length);
    const helper = Math.abs(normal.y) < 0.9 ? new Vector3(0, 1, 0) : new Vector3(1, 0, 0);
    const u = normal.clone().cross(helper).normalize();
    const v = normal.clone().cross(u).normalize();
    cap.sort((a, b) => {
      const pa = a.clone().sub(center);
      const pb = b.clone().sub(center);
      return Math.atan2(pa.dot(v), pa.dot(u)) - Math.atan2(pb.dot(v), pb.dot(u));
    });
    next.push(cap);
  }
  return next;
}

/** Scalar tint is intentionally subtle; the shared art shader applies its strength. */
export function applyStoneTint(geometry: BufferGeometry, seed: number): BufferGeometry {
  const positions = geometry.getAttribute('position');
  const base = Math.sin(seed * 12.9898 + 0.73) * 0.65;
  const tint = new Float32Array(positions.count);
  for (let i = 0; i < positions.count; i++) {
    tint[i] = base + Math.sin(positions.getX(i) * 1.6 + positions.getZ(i) * 2.3 + seed) * 0.25;
  }
  geometry.setAttribute('stoneTint', new Float32BufferAttribute(tint, 1));
  return geometry;
}

/** Convex low-poly prism, clipped into planar bevels and a single optional corner chip. */
export function createStonePrismGeometry(outline: readonly Point2[], height: number, options: StoneGeometryOptions): BufferGeometry {
  if (outline.length < 3 || height <= 0) throw new Error('Stone prism needs a polygon and positive height.');
  let points = outline.map(([x, z]) => [x, z] as Point2);
  const area = points.reduce((sum, p, i) => {
    const q = points[(i + 1) % points.length]!;
    return sum + p[0] * q[1] - q[0] * p[1];
  }, 0);
  if (area > 0) points = points.reverse();
  const half = height / 2;
  const top = points.map(([x, z]) => new Vector3(x, half, z));
  const bottom = points.map(([x, z]) => new Vector3(x, -half, z));
  let faces: Polygon[] = [top, [...bottom].reverse()];
  const sides: { normal: Vector3; distance: number }[] = [];
  for (let i = 0; i < points.length; i++) {
    const j = (i + 1) % points.length;
    const a = bottom[i]!;
    const b = bottom[j]!;
    faces.push([a, b, top[j]!, top[i]!]);
    const normal = b.clone().sub(a).cross(new Vector3(0, 1, 0)).normalize();
    sides.push({ normal, distance: normal.dot(a) });
  }
  const bevel = Math.min(options.bevel, height * 0.2);
  for (let i = 0; i < sides.length; i++) {
    const side = sides[i]!;
    for (const sign of [-1, 1]) {
      const n = side.normal.clone().add(new Vector3(0, sign, 0));
      const d = (side.distance + half - bevel) / n.length();
      faces = clip(faces, n.normalize(), d);
    }
    const previous = sides[(i + sides.length - 1) % sides.length]!;
    const n = previous.normal.clone().add(side.normal);
    const d = (previous.distance + side.distance - options.cornerCut) / n.length();
    faces = clip(faces, n.normalize(), d);
  }
  if (options.chipSize && options.chipSize > 0) {
    const index = (options.chipCorner ?? 0) % sides.length;
    const a = sides[(index + sides.length - 1) % sides.length]!;
    const b = sides[index]!;
    const n = a.normal.clone().add(b.normal).add(new Vector3(0, 1, 0));
    const d = (a.distance + b.distance + half - options.chipSize) / n.length();
    faces = clip(faces, n.normalize(), d);
  }

  const vertices: number[] = [];
  const normals: number[] = [];
  for (const face of faces) {
    const center = face.reduce((sum, p) => sum.add(p), new Vector3()).divideScalar(face.length);
    const faceNormal = new Vector3();
    for (let i = 0; i < face.length; i++) {
      faceNormal.add(face[i]!.clone().sub(center).cross(face[(i + 1) % face.length]!.clone().sub(center)));
    }
    if (faceNormal.lengthSq() < EPSILON * EPSILON) continue;
    faceNormal.normalize();
    // A center fan preserves shared boundary vertices, including collinear ones.
    for (let i = 0; i < face.length; i++) {
      const a = face[i]!;
      const b = face[(i + 1) % face.length]!;
      if (a.clone().sub(center).cross(b.clone().sub(center)).lengthSq() < EPSILON * EPSILON) continue;
      for (const p of [center, a, b]) {
        vertices.push(p.x, p.y, p.z);
        normals.push(faceNormal.x, faceNormal.y, faceNormal.z);
      }
    }
  }
  const geometry = new BufferGeometry();
  geometry.setAttribute('position', new Float32BufferAttribute(vertices, 3));
  geometry.setAttribute('normal', new Float32BufferAttribute(normals, 3));
  applyStoneTint(geometry, options.seed);
  geometry.computeBoundingBox();
  geometry.computeBoundingSphere();
  geometry.userData.stoneSolid = true;
  return geometry;
}

export function createStoneBlockGeometry(width: number, height: number, depth: number, options: StoneGeometryOptions): BufferGeometry {
  const x = width / 2;
  const z = depth / 2;
  return createStonePrismGeometry([[-x, -z], [-x, z], [x, z], [x, -z]], height, options);
}

src/materials/createArtMaterial.ts.content:
import { Color, MeshLambertMaterial, Vector4 } from 'three';
import { lightingConfig } from '../config/lighting';
import { palette } from '../config/palette';
import { stoneConfig } from '../config/stone';
import { vegetationConfig } from '../config/vegetation';
import { applyEnvironmentMotion } from './applyEnvironmentMotion';
import type { EnvironmentState } from '../animation/environmentMotion';

type ArtSurface = 'ground' | 'stone' | 'water' | 'foliage' | 'flower';

/** Keep Three's geometry, depth and real shadow pipeline; replace only the color response. */
export function createArtMaterial(surface: ArtSurface, environment?: EnvironmentState) {
  const material = new MeshLambertMaterial();
  const plant = surface === 'foliage' || surface === 'flower';
  material.name = `courtyard-${surface}`;
  material.userData.artSurface = surface;
  const environmentEnabled = environment?.options.enabled && (plant || surface === 'ground');
  material.customProgramCacheKey = () => `courtyard-art-${surface}-v3${environmentEnabled ? '-environment-v1' : ''}`;

  material.onBeforeCompile = (shader) => {
    const trees = lightingConfig.treeShadows;
    const ground = vegetationConfig.ground;
    const detail = vegetationConfig.treeDetail;
    Object.assign(shader.uniforms, {
      uArtSunAmount: { value: lightingConfig.sun.intensity },
      uArtFillAmount: { value: lightingConfig.fill.intensity },
      uArtStoneVariation: { value: stoneConfig.colorVariation },
      uArtGrass: { value: new Color(palette.grassBase) },
      uArtGrassLight: { value: new Color(palette.grassLight) },
      uArtGrassDark: { value: new Color(palette.grassDark) },
      uArtGrassShadow: { value: new Color(palette.treeShadow) },
      uArtStoneTop: { value: new Color(palette.stoneLight) },
      uArtStoneSide: { value: new Color(palette.stoneSide) },
      uArtStoneShade: { value: new Color(palette.stoneShade) },
      uArtWater: { value: new Color(palette.waterBase) },
      uArtWaterShade: { value: new Color(palette.waterShade) },
      uArtPlantShade: { value: new Color(palette.plantShade) },
      uArtFlowerShade: { value: new Color(palette.flowerShade) },
      uArtFlowerCenter: { value: new Color(palette.flowerCenter) },
      uArtGroundEnabled: { value: ground.enabled ? 1 : 0 },
      uArtGroundScales: { value: new Vector4(ground.macroScale, ground.macroStrength, ground.detailScale, ground.detailStrength) },
      uArtGroundDensity: { value: ground.detailDensity },
      uArtQuietRegion: { value: new Vector4(ground.quietCenter[0], ground.quietCenter[1], ground.quietRadius[0], ground.quietRadius[1]) },
      uArtTreeDetailEnabled: { value: detail.enabled ? 1 : 0 },
      uArtTreeDetail: { value: new Vector4(detail.branchScale, detail.leafScale, detail.edgeBreakup, detail.gapStrength) },
      uArtTreesEnabled: { value: trees.enabled ? 1 : 0 },
      uArtTreeNoiseScale: { value: trees.edgeNoiseScale },
      uArtTreeNoiseAmount: { value: trees.edgeNoiseAmount },
      uArtTreeSoftness: { value: trees.edgeSoftness },
      uArtTreePatches: {
        value: trees.patches.map(p => new Vector4(p.center[0], p.center[1], p.radius[0], p.radius[1])),
      },
      uArtTreeRotations: { value: trees.patches.map(p => p.rotation) },
    });

    shader.vertexShader = shader.vertexShader
      .replace('#include <common>', `#include <common>\nvarying vec3 vArtWorldPosition;
        ${surface === 'stone' ? 'attribute float stoneTint; varying float vArtStoneTint;' : ''}
        ${plant ? 'attribute float plantPart; attribute float plantHeight; varying float vArtPlantPart; varying float vArtPlantHeight;' : ''}
      `)
      .replace('#include <worldpos_vertex>', `#include <worldpos_vertex>
        vec4 artPosition = vec4(transformed, 1.0);
        #ifdef USE_BATCHING
          artPosition = batchingMatrix * artPosition;
        #endif
        #ifdef USE_INSTANCING
          artPosition = instanceMatrix * artPosition;
        #endif
        vArtWorldPosition = (modelMatrix * artPosition).xyz;
        ${surface === 'stone' ? 'vArtStoneTint = stoneTint;' : ''}
        ${plant ? 'vArtPlantPart = plantPart; vArtPlantHeight = plantHeight;' : ''}
      `);

    const declarations = /* glsl */`
      varying vec3 vArtWorldPosition;
      ${surface === 'stone' ? 'varying float vArtStoneTint; uniform float uArtStoneVariation;' : ''}
      ${plant ? 'varying float vArtPlantPart; varying float vArtPlantHeight;' : ''}
      uniform float uArtSunAmount;
      uniform float uArtFillAmount;
      uniform vec3 uArtGrass;
      uniform vec3 uArtGrassLight;
      uniform vec3 uArtGrassDark;
      uniform vec3 uArtGrassShadow;
      uniform vec3 uArtStoneTop;
      uniform vec3 uArtStoneSide;
      uniform vec3 uArtStoneShade;
      uniform vec3 uArtWater;
      uniform vec3 uArtWaterShade;
      uniform vec3 uArtPlantShade;
      uniform vec3 uArtFlowerShade;
      uniform vec3 uArtFlowerCenter;
      uniform float uArtGroundEnabled;
      uniform vec4 uArtGroundScales;
      uniform float uArtGroundDensity;
      uniform vec4 uArtQuietRegion;
      uniform float uArtTreeDetailEnabled;
      uniform vec4 uArtTreeDetail;
      uniform float uArtTreesEnabled;
      uniform float uArtTreeNoiseScale;
      uniform float uArtTreeNoiseAmount;
      uniform float uArtTreeSoftness;
      uniform vec4 uArtTreePatches[${trees.patches.length}];
      uniform float uArtTreeRotations[${trees.patches.length}];

      float artHash(vec2 p) {
        return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
      }
      float artNoise(vec2 p) {
        vec2 cell = floor(p);
        vec2 f = fract(p);
        vec2 t = f * f * (3.0 - 2.0 * f);
        return mix(mix(artHash(cell), artHash(cell + vec2(1.0, 0.0)), t.x),
                   mix(artHash(cell + vec2(0.0, 1.0)), artHash(cell + vec2(1.0)), t.x), t.y);
      }
      float artCanopy(vec2 position) {
        float distanceToCanopy = 10.0;
        for (int i = 0; i < ${trees.patches.length}; i++) {
          vec4 canopyBounds = uArtTreePatches[i];
          float c = cos(uArtTreeRotations[i]);
          float s = sin(uArtTreeRotations[i]);
          vec2 local = mat2(c, -s, s, c) * (position - canopyBounds.xy);
          float d = length(local / canopyBounds.zw);
          d += (artNoise(position * uArtTreeNoiseScale) - 0.5) * uArtTreeNoiseAmount;
          distanceToCanopy = min(distanceToCanopy, d);
        }
        float silhouette = 1.0 - smoothstep(1.0 - uArtTreeSoftness, 1.0 + uArtTreeSoftness, distanceToCanopy);
        if (uArtTreeDetailEnabled < 0.5) return silhouette * uArtTreesEnabled;
        float branches = artNoise(position * uArtTreeDetail.x + vec2(8.3, 3.7));
        float leaves = artHash(floor(position * uArtTreeDetail.y));
        float brokenDistance = distanceToCanopy + (branches - 0.5) * uArtTreeDetail.z + (leaves - 0.5) * 0.06;
        float body = 1.0 - smoothstep(1.0 - uArtTreeSoftness, 1.0 + uArtTreeSoftness, brokenDistance);
        float holes = step(0.74, branches) * step(0.68, artNoise(position * 8.5));
        float edge = step(0.68, distanceToCanopy);
        float gaps = max(holes, edge * step(0.78, leaves) * step(0.44, branches)) * uArtTreeDetail.w;
        float fragments = (1.0 - body) * step(distanceToCanopy, 1.12)
          * step(0.76, leaves) * step(0.56, branches);
        return max(body * (1.0 - gaps), fragments) * uArtTreesEnabled;
      }
    `;

    const response: Record<ArtSurface, string> = {
      ground: /* glsl */`
        float daylight = clamp(uArtSunAmount * 0.8 + uArtFillAmount * 0.2, 0.0, 1.0);
        vec3 sunlitGrass = mix(uArtGrassDark, uArtGrass, daylight);
        vec2 groundPosition = vArtWorldPosition.xz;
        float quiet = 1.0 - smoothstep(0.7, 1.2, length((groundPosition - uArtQuietRegion.xy) / uArtQuietRegion.zw));
        float macro = artNoise(groundPosition * uArtGroundScales.x + vec2(4.2, 7.3));
        vec3 groundVariation = mix(uArtGrassDark, uArtGrassLight, smoothstep(0.18, 0.86, macro));
        sunlitGrass = mix(sunlitGrass, groundVariation, uArtGroundScales.y * (1.0 - quiet * 0.65) * uArtGroundEnabled);
        vec2 detailCell = floor(groundPosition * uArtGroundScales.z);
        float speckle = step(1.0 - uArtGroundDensity, artHash(detailCell)) * (artHash(detailCell + vec2(3.2, 9.1)) * 2.0 - 1.0);
        sunlitGrass *= 1.0 + speckle * uArtGroundScales.w * (1.0 - quiet * 0.85) * uArtGroundEnabled;
        float occlusion = max(1.0 - getShadowMask(), artCanopy(vArtWorldPosition.xz));
        outgoingLight = mix(sunlitGrass, uArtGrassShadow, occlusion);
      `,
      stone: /* glsl */`
        vec3 worldNormal = inverseTransformDirection(normal, viewMatrix);
        float sunFacing = 0.0;
        #if NUM_DIR_LIGHTS > 0
          sunFacing = max(dot(normal, directionalLights[0].direction), 0.0);
        #endif
        float sunAmount = clamp(uArtSunAmount, 0.0, 1.0);
        float fillAmount = clamp(uArtFillAmount, 0.0, 1.0);
        vec3 coolFace = uArtStoneShade * mix(0.72, 1.0, fillAmount);
        vec3 sideFace = mix(coolFace, uArtStoneSide, smoothstep(0.02, 0.56, sunFacing) * sunAmount);
        vec3 topFace = mix(uArtStoneSide, uArtStoneTop, sunAmount);
        vec3 litStone = mix(sideFace, topFace, smoothstep(0.65, 0.95, worldNormal.y));
        vec3 shadedStone = mix(coolFace, litStone, 0.12 * fillAmount);
        outgoingLight = mix(shadedStone, litStone, getShadowMask());
        outgoingLight *= 1.0 + vArtStoneTint * uArtStoneVariation;
      `,
      water: /* glsl */`
        outgoingLight = mix(uArtWaterShade, uArtWater, getShadowMask());
      `,
      foliage: /* glsl */`
        float plantOcclusion = max(1.0 - getShadowMask(), artCanopy(vArtWorldPosition.xz));
        vec3 litPlant = diffuseColor.rgb * mix(0.93, 1.0, clamp(vArtPlantHeight, 0.0, 1.0));
        outgoingLight = mix(litPlant, uArtPlantShade, plantOcclusion);
      `,
      flower: /* glsl */`
        float flowerOcclusion = max(1.0 - getShadowMask(), artCanopy(vArtWorldPosition.xz));
        vec3 litFlower = mix(diffuseColor.rgb, uArtFlowerCenter, vArtPlantPart);
        vec3 shadedFlower = mix(uArtFlowerShade, uArtFlowerCenter * 0.65, vArtPlantPart);
        outgoingLight = mix(litFlower, shadedFlower, flowerOcclusion);
      `,
    };

    shader.fragmentShader = shader.fragmentShader
      .replace('#include <common>', `#include <common>\n${declarations}`)
      .replace('#include <shadowmap_pars_fragment>', '#include <shadowmap_pars_fragment>\n#include <shadowmask_pars_fragment>')
      .replace('#include <opaque_fragment>', `${response[surface]}\n#include <opaque_fragment>`);
    if (environmentEnabled) applyEnvironmentMotion(shader, plant, environment!);
  };

  return material;
}

