}

src/materials/createWaterMaterial.ts.content:
import { Color, Vector4 } from 'three';
import { createArtMaterial } from './createArtMaterial';
import { layoutConfig } from '../config/layout';
import { waterConfig } from '../config/water';

export function createWaterState() {
  return {
    time: { value: waterConfig.initialTime as number },
    impacts: { value: Array.from({ length: waterConfig.ripples.capacity }, () => new Vector4(0, 0, 0, 0)) },
  };
}
export type WaterState = ReturnType<typeof createWaterState>;

/** Extend only water's final color; Three.js depth, normals and actual shadows are retained. */
export function createWaterMaterial(state: WaterState = createWaterState(), kind: 'surface' | 'jet' = 'surface') {
  const material = createArtMaterial('water');
  material.name = `courtyard-water-${kind}`;
  material.flatShading = kind === 'jet';
  material.userData.waterKind = kind;
  material.customProgramCacheKey = () => `courtyard-water-${kind}-v1`;
  const baseCompile = material.onBeforeCompile.bind(material);
  material.onBeforeCompile = (shader, renderer) => {
    baseCompile(shader, renderer);
    const f = layoutConfig.fountain;
    Object.assign(shader.uniforms, {
      uWaterTime: state.time,
      uWaterImpacts: state.impacts,
      uWaterEnabled: { value: waterConfig.enabled ? 1 : 0 },
      uWaterBase: { value: new Color(waterConfig.colors.base) },
      uWaterDeep: { value: new Color(waterConfig.colors.deep) },
      uWaterShade: { value: new Color(waterConfig.colors.shade) },
      uWaterWhite: { value: new Color(waterConfig.colors.highlight) },
      uWaterJet: { value: new Color(waterConfig.colors.jet) },
      uWaterOrigin: { value: new Vector4(f.position[0], f.position[2], Math.cos(f.rotationY), Math.sin(f.rotationY)) },
      uWaterSurface: { value: new Vector4(waterConfig.surface.flowSpeed, waterConfig.surface.reflectionThreshold, waterConfig.surface.waveSpeed, waterConfig.surface.waveStrength) },
      uWaterRipple: { value: new Vector4(waterConfig.ripples.lifetime, waterConfig.ripples.speed, waterConfig.ripples.strength, f.innerRadius * Math.cos(Math.PI / 8)) },
    });
    const declarations = /* glsl */`
      uniform float uWaterTime;
      uniform float uWaterEnabled;
      uniform vec4 uWaterImpacts[${waterConfig.ripples.capacity}];
      uniform vec3 uWaterBase;
      uniform vec3 uWaterDeep;
      uniform vec3 uWaterShade;
      uniform vec3 uWaterWhite;
      uniform vec3 uWaterJet;
      uniform vec4 uWaterOrigin;
      uniform vec4 uWaterSurface;
      uniform vec4 uWaterRipple;
    `;
    const surface = /* glsl */`
      vec2 delta = vArtWorldPosition.xz - uWaterOrigin.xy;
      vec2 p = vec2(uWaterOrigin.z * delta.x - uWaterOrigin.w * delta.y,
                    uWaterOrigin.w * delta.x + uWaterOrigin.z * delta.y);
      float t = uWaterTime;
      vec2 drift = vec2(t * uWaterSurface.x, -t * uWaterSurface.x * 0.5);
      float warp = artNoise(p * 4.7 + vec2(-t * 0.022, t * 0.04));
      float field = artNoise(p * 1.8 + vec2(3.1, 6.4) + drift * 0.6);
      float leftBias = 1.0 - smoothstep(-1.6, 0.8, p.x);
      float brokenEdge = (artNoise(p * 22.0 + drift * 2.0) - 0.5) * 0.07;
      float reflection = smoothstep(uWaterSurface.y, uWaterSurface.y + 0.045, field * 0.88 + warp * 0.12 + leftBias * 0.12 + brokenEdge);
      float distanceFromCenter = length(p);
      float wave = smoothstep(0.94, 0.995, sin(distanceFromCenter * 14.0 - t * uWaterSurface.z * 14.0 + warp * 0.5));
      wave *= smoothstep(0.25, 0.5, distanceFromCenter) * (1.0 - smoothstep(1.2, 1.85, distanceFromCenter)) * uWaterSurface.w;
      wave *= smoothstep(0.24, 0.75, artNoise(p * 8.5 + drift));
      float glint = smoothstep(0.80, 0.94, artNoise(p * 9.0 + drift * 1.2))
        * smoothstep(0.72, 0.96, sin((p.x + p.y * 0.7) * 18.0 - t * 1.3 + warp * 7.0)) * 0.8;
      float impactRings = 0.0;
      for (int i = 0; i < ${waterConfig.ripples.capacity}; i++) {
        vec4 impact = uWaterImpacts[i];
        float age = impact.z;
        float radius = 0.025 + age * uWaterRipple.y;
        float ring = 1.0 - smoothstep(0.012, 0.022, abs(length(p - impact.xy) - radius));
        float fade = pow(clamp(1.0 - age / uWaterRipple.x, 0.0, 1.0), 2.0);
        impactRings = max(impactRings, ring * fade * impact.w * uWaterRipple.z);
      }
      float wallDistance = 10.0;
      for (int i = 0; i < 8; i++) {
        float angle = (float(i) + 0.5) * PI / 4.0;
        wallDistance = min(wallDistance, uWaterRipple.w - dot(p, vec2(cos(angle), -sin(angle))));
      }
      float edgeFoam = (1.0 - smoothstep(0.025, 0.07, wallDistance))
        * smoothstep(0.48, 0.72, artNoise(p * 14.0 + drift)) * 0.4;
      float whiteAmount = clamp(max(max(glint, wave), max(impactRings, edgeFoam)), 0.0, 0.85);
      vec3 litWater = mix(uWaterBase, uWaterDeep, reflection);
      litWater = mix(litWater, uWaterWhite, whiteAmount);
      vec3 shadedWater = mix(uWaterShade, uWaterDeep * 0.8, reflection * 0.8);
      shadedWater = mix(shadedWater, uWaterWhite, whiteAmount * 0.18);
      vec3 dynamicWater = mix(shadedWater, litWater, getShadowMask());
      outgoingLight = mix(mix(uArtWaterShade, uArtWater, getShadowMask()), dynamicWater, uWaterEnabled);
    `;
    const jet = /* glsl */`
      vec3 waterNormal = inverseTransformDirection(normal, viewMatrix);
      float lightFace = smoothstep(-0.2, 0.8, waterNormal.y);
      float crownSparkle = pow(max(waterNormal.y, 0.0), 14.0) * 0.25;
      vec3 litJet = mix(uWaterJet, uWaterWhite, lightFace * 0.4 + crownSparkle);
      outgoingLight = mix(uWaterShade, litJet, getShadowMask());
    `;
    const anchor = 'outgoingLight = mix(uArtWaterShade, uArtWater, getShadowMask());';
    if (!shader.fragmentShader.includes(anchor)) throw new Error('Water shader extension anchor changed.');
    shader.fragmentShader = shader.fragmentShader
      .replace('void main() {', `${declarations}\nvoid main() {`)
      .replace(anchor, kind === 'surface' ? surface : jet);
  };
  return material;
}

src/materials/applyEnvironmentMotion.ts.content:
import type { MeshLambertMaterial } from 'three';
import { environmentConfig as config } from '../config/environment';
import { windDirection } from '../animation/environmentMotion';
import type { EnvironmentState } from '../animation/environmentMotion';

type ArtShader = Parameters<MeshLambertMaterial['onBeforeCompile']>[0];
const gl = (value: number) => value.toFixed(10);

const windDeclarations = /* glsl */`
  uniform float uEnvironmentTime;
  uniform float uEnvironmentWind;
  attribute vec3 windRoot;
  attribute vec4 windShape; // height, maximum angle, position phase, rigid head
  const vec2 windDirection = vec2(${windDirection.map(gl).join(',')});
  float plantWindAngle(vec4 shape) {
    float gust = 0.68 + 0.32 * sin(6.28318530718 * uEnvironmentTime / ${gl(config.wind.gustPeriod)} + shape.z * 0.23);
    return shape.y * gust * (0.78 * sin(6.28318530718 * uEnvironmentTime / ${gl(config.wind.periods[0])} + shape.z)
      + 0.22 * sin(6.28318530718 * uEnvironmentTime / ${gl(config.wind.periods[1])} + shape.z * 1.3));
  }
  vec3 rotatePlantWind(vec3 v, float angle) {
    float along = dot(v.xz, windDirection);
    float a2 = angle * angle;
    float c = 1.0 - a2 * (0.5 - a2 / 24.0 + a2 * a2 / 720.0);
    float s = angle * (1.0 - a2 / 6.0 + a2 * a2 / 120.0);
    vec2 horizontal = v.xz + windDirection * (along * (c - 1.0) + v.y * s);
    return vec3(horizontal.x, v.y * c - along * s, horizontal.y);
  }
  vec3 bendPlantWind(vec3 rest, vec3 root, vec4 shape) {
    float height = shape.x;
    float y = shape.w > 0.5 ? height : clamp(rest.y - root.y, 0.0, height);
    float turn = plantWindAngle(shape) * y / height;
    float t2 = turn * turn;
    // Angles are bounded to 8 degrees. These forms remain precise near still poses.
    float sinc = 1.0 - t2 / 6.0 + t2 * t2 / 120.0;
    float cosc = turn * (0.5 - t2 / 24.0 + t2 * t2 / 720.0);
    vec3 center = root + vec3(windDirection.x * y * cosc, y * sinc, windDirection.y * y * cosc);
    return center + rotatePlantWind(rest - root - vec3(0.0, y, 0.0), turn);
  }
  vec3 bendPlantWindNormal(vec3 rest, vec3 root, vec4 shape, vec3 normal) {
    float angle = plantWindAngle(shape);
    float y = shape.w > 0.5 ? shape.x : clamp(rest.y - root.y, 0.0, shape.x);
    // Inverse-transpose of the arc deformation, then rotate into its tangent.
    if (shape.w < 0.5) normal.y /= 1.0 - angle / shape.x * dot((rest - root).xz, windDirection);
    return rotatePlantWind(normal, angle * y / shape.x);
  }
`;

const canopyDeclarations = /* glsl */`
  uniform float uEnvironmentTime;
  uniform float uEnvironmentCanopy;
  float environmentCanopyWave(vec2 p) {
    float gust = 0.68 + 0.32 * sin(6.28318530718 * uEnvironmentTime / ${gl(config.wind.gustPeriod)} + dot(p, vec2(0.06, 0.04)));
    return uEnvironmentCanopy * gust * (
      0.76 * sin(6.28318530718 * uEnvironmentTime / ${gl(config.canopy.period)} + dot(p, vec2(0.35, 0.11)))
      + 0.24 * sin(6.28318530718 * uEnvironmentTime / ${gl(config.canopy.secondaryPeriod)} + dot(p, vec2(-0.12, 0.42))));
  }
`;

/** Extend the art response without replacing real shadow reception or instance colors. */
export function applyEnvironmentMotion(shader: ArtShader, plant: boolean, state: EnvironmentState) {
  shader.uniforms.uEnvironmentTime = state.time;
  shader.uniforms.uEnvironmentWind = state.wind;
  shader.uniforms.uEnvironmentCanopy = state.canopy;
  if (plant) {
    shader.vertexShader = shader.vertexShader
      .replace('#include <common>', `#include <common>\n${windDeclarations}`)
      .replace('#include <beginnormal_vertex>', `#include <beginnormal_vertex>
        #ifdef USE_INSTANCING
          if (uEnvironmentWind > 0.5) {
            mat3 windMatrix = mat3(instanceMatrix);
            vec3 windNormal = windMatrix * (objectNormal / vec3(dot(windMatrix[0], windMatrix[0]), dot(windMatrix[1], windMatrix[1]), dot(windMatrix[2], windMatrix[2])));
            windNormal = bendPlantWindNormal((instanceMatrix * vec4(position, 1.0)).xyz, windRoot, windShape, windNormal);
            objectNormal = vec3(dot(windMatrix[0], windNormal), dot(windMatrix[1], windNormal), dot(windMatrix[2], windNormal));
          }
        #endif
      `)
      .replace('#include <begin_vertex>', `#include <begin_vertex>
        #ifdef USE_INSTANCING
          if (uEnvironmentWind > 0.5) {
            mat3 windMatrix = mat3(instanceMatrix);
            vec3 windRest = (instanceMatrix * vec4(transformed, 1.0)).xyz;
            vec3 windDelta = bendPlantWind(windRest, windRoot, windShape) - windRest;
            transformed += vec3(dot(windMatrix[0], windDelta) / dot(windMatrix[0], windMatrix[0]),
              dot(windMatrix[1], windDelta) / dot(windMatrix[1], windMatrix[1]),
              dot(windMatrix[2], windDelta) / dot(windMatrix[2], windMatrix[2]));
          }
        #endif
      `);
  }
  shader.fragmentShader = shader.fragmentShader
    .replace('#include <common>', `#include <common>\n${canopyDeclarations}`)
    .replace('float artCanopy(vec2 position) {', `float artCanopy(vec2 position) {
      float environmentWave = environmentCanopyWave(position);`)
    .replace('distanceToCanopy = min(distanceToCanopy, d);', `
      float edgeBand = smoothstep(0.84, 0.94, d) * (1.0 - smoothstep(1.14, 1.24, d));
      float distanceGradient = length(local / (canopyBounds.zw * canopyBounds.zw)) / max(length(local / canopyBounds.zw), 0.001);
      d += environmentWave * ${gl(config.canopy.displacement)} * distanceGradient * edgeBand;
      distanceToCanopy = min(distanceToCanopy, d);`)
    .replace('float holes = step(0.74, branches) * step(0.68, artNoise(position * 8.5));',
      `float holes = step(0.74, branches) * step(0.68, artNoise(position * 8.5));
       holes *= 1.0 - uEnvironmentCanopy * ${gl(config.canopy.holeShade)} * (0.5 + 0.5 * environmentWave);`);
}

src/rendering/createRenderer.ts.content:
import { NoToneMapping, PCFShadowMap, SRGBColorSpace, Vector2, WebGLRenderer } from 'three';
import type { Camera, Scene } from 'three';
import { renderConfig } from '../config/scene';
import type { RenderMode } from '../config/scene';
import { resolveVisualOptions } from '../config/visual';
import type { PixelOptions } from '../config/visual';
import { createPixelPipeline } from './createPixelPipeline';
import { releaseSceneGpuResources } from './releaseSceneGpuResources';

export function createRenderer(
  host: HTMLElement,
  initialMode: RenderMode,
  onAspectChange: (aspect: number) => void,
  pixelOptions: PixelOptions = resolveVisualOptions(new URLSearchParams()),
) {
  const renderer = new WebGLRenderer({ antialias: false, alpha: false });
  renderer.outputColorSpace = SRGBColorSpace;
  renderer.toneMapping = NoToneMapping;
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = PCFShadowMap;
  // Only static buildings cast shadows; animated water and vegetation are receivers.
  renderer.shadowMap.autoUpdate = false;
  renderer.shadowMap.needsUpdate = true;
  renderer.info.autoReset = false;
  const pixels = createPixelPipeline(renderer, pixelOptions);
  const outputSize = new Vector2();

  const canvas = renderer.domElement;
  canvas.setAttribute('role', 'img');
  canvas.setAttribute('aria-label', '固定俯视庭院：石柱和粉紫小花围绕八边形喷泉，蓝白水面流动，草花随风轻摆，树影边缘缓慢变化，可暂停整个场景动效。');
  host.append(canvas);

  let mode = initialMode;
  let disposed = false;
  let contextLost = false;
  let suspended = false;
  let animating = true;
  let draw: ((timestamp: number) => void) | undefined;
  let activeScene: Scene | undefined;

  function syncLoop() {
    const available = !disposed && !contextLost && !suspended;
    renderer.setAnimationLoop(available && animating && draw ? draw : null);
    if (available && !animating) draw?.(performance.now());
  }

  function resize() {
    const bounds = host.getBoundingClientRect();
    if (bounds.width <= 0 || bounds.height <= 0 || disposed) return;

    const deviceRatio = Math.min(window.devicePixelRatio || 1, renderConfig.maxDevicePixelRatio);

    renderer.setPixelRatio(deviceRatio);
    renderer.setSize(
      Math.max(1, Math.floor(bounds.width)),
      Math.max(1, Math.floor(bounds.height)),
      false,
    );
    renderer.getDrawingBufferSize(outputSize);
    pixels.resize(outputSize.x, outputSize.y);
    canvas.dataset.renderMode = mode;
    const info = pixels.getInfo();
    canvas.dataset.sampleWidth = String(mode === 'pixel' ? info.sampleWidth : outputSize.x);
    canvas.dataset.sampleHeight = String(mode === 'pixel' ? info.sampleHeight : outputSize.y);
    canvas.dataset.pixelProfile = String(info.designResolution);
    canvas.dataset.finish = info.finish;
    onAspectChange(bounds.width / bounds.height);
    if (!animating && !suspended && !contextLost) draw?.(performance.now());
  }

  function onContextLost(event: Event) {
    event.preventDefault();
    contextLost = true;
    host.dataset.renderState = 'context-lost';
    syncLoop();
    // Three.js rebuilds its caches on restore. Remove callbacks to the old GPU
    // generation now, while deletes are ignored by the lost context.
    pixels.releaseGpuResources();
    if (activeScene) releaseSceneGpuResources(activeScene);
  }

  function onContextRestored() {
    contextLost = false;
    renderer.shadowMap.needsUpdate = true;
    resize();
    syncLoop();
  }

  canvas.addEventListener('webglcontextlost', onContextLost);
  canvas.addEventListener('webglcontextrestored', onContextRestored);
  const observer = new ResizeObserver(resize);
  observer.observe(host);
  window.addEventListener('resize', resize);
  let dprQuery: MediaQueryList;
  function watchDpr() {
    dprQuery?.removeEventListener('change', onDprChange);
    dprQuery = window.matchMedia(`(resolution: ${window.devicePixelRatio}dppx)`);
    dprQuery.addEventListener('change', onDprChange);
  }
  function onDprChange() { watchDpr();resize(); }
  watchDpr();
  resize();

  return {
    canvas,
    setMode(nextMode: RenderMode) {
      mode = nextMode;
      resize();
    },
    setAnimating(value: boolean) { animating = value; syncLoop(); },
    setSuspended(value: boolean) { suspended = value; syncLoop(); },
    renderOnce() { draw?.(performance.now()); },
    getStats() {
      return {
        geometries: renderer.info.memory.geometries,
        textures: renderer.info.memory.textures,
        programs: renderer.info.programs?.length ?? 0,
        calls: renderer.info.render.calls,
        triangles: renderer.info.render.triangles,
        mode,
        outputWidth: renderer.domElement.width,
        outputHeight: renderer.domElement.height,
        pixel: mode === 'pixel' ? pixels.getInfo() : null,
      };
    },
    start(scene: Scene, camera: Camera, update?: (timestamp: number) => void) {
      activeScene = scene;
      draw = (timestamp) => {
        if (disposed || contextLost || suspended) return;
        update?.(timestamp);
        renderer.info.reset();
        if (mode === 'pixel') pixels.render(scene, camera);
        else {
          renderer.setRenderTarget(null);
          renderer.render(scene, camera);
        }
        host.dataset.renderState = 'ready';
      };
      syncLoop();
    },
    dispose() {
      if (disposed) return;
      disposed = true;
      observer.disconnect();
      window.removeEventListener('resize', resize);
      dprQuery.removeEventListener('change', onDprChange);
      canvas.removeEventListener('webglcontextlost', onContextLost);
      canvas.removeEventListener('webglcontextrestored', onContextRestored);
      renderer.setAnimationLoop(null);
      draw = undefined;
      activeScene = undefined;
      pixels.dispose();
      renderer.dispose();
      canvas.remove();
    },
  };
}

src/rendering/releaseSceneGpuResources.t.content:
import { DirectionalLight, InstancedMesh, Mesh } from 'three';
import type { BufferGeometry, Material, Scene } from 'three';

/** Detach the lost GPU generation while retaining all CPU scene/instance data. */
export function releaseSceneGpuResources(scene: Scene) {
  const geometries = new Set<BufferGeometry>();
  const materials = new Set<Material>();
  scene.traverse((object) => {
    if (object instanceof Mesh) {
      geometries.add(object.geometry);
      for (const material of Array.isArray(object.material) ? object.material : [object.material]) {
        materials.add(material);
      }
    }
    if (object instanceof InstancedMesh) object.dispose();
    if (object instanceof DirectionalLight) {
      object.shadow.map?.dispose();
      object.shadow.mapPass?.dispose();
    }
  });
  for (const geometry of geometries) geometry.dispose();
  for (const material of materials) material.dispose();
}

src/rendering/createPixelPipeline.ts.content:
import {
  BufferGeometry, Float32BufferAttribute, HalfFloatType, LinearSRGBColorSpace,
  Mesh, NearestFilter, OrthographicCamera, Scene, ShaderMaterial,
  SRGBColorSpace, UnsignedByteType, Vector2, WebGLRenderTarget,
} from 'three';
import type { Camera, WebGLRenderer } from 'three';
import { visualConfig } from '../config/visual';
import type { PixelOptions } from '../config/visual';

/** Linear scene target -> texel-center lookup -> one final sRGB output. */
export function createPixelPipeline(renderer: WebGLRenderer, options: PixelOptions) {
  const halfFloat = options.storage !== 'byte' && renderer.extensions.has('EXT_color_buffer_float');
  const target = new WebGLRenderTarget(1, 1, {
    type: halfFloat ? HalfFloatType : UnsignedByteType,
    minFilter: NearestFilter,
    magFilter: NearestFilter,
    generateMipmaps: false,
    depthBuffer: true,
    stencilBuffer: false,
  });
  // SRGB8 attachments perform storage encoding / sample decoding in hardware.
  // This avoids dark-color loss on devices without renderable half-float targets.
  target.texture.colorSpace = halfFloat ? LinearSRGBColorSpace : SRGBColorSpace;
  target.texture.name = 'courtyard-pixel-scene';
  const geometry = new BufferGeometry();
  geometry.setAttribute('position', new Float32BufferAttribute([-1, -1, 0, 3, -1, 0, -1, 3, 0], 3));
  geometry.setAttribute('uv', new Float32BufferAttribute([0, 0, 2, 0, 0, 2], 2));
  const finish = visualConfig.finishes[options.finish];
  const material = new ShaderMaterial({
    name: 'courtyard-pixel-output',
    depthTest: false,
    depthWrite: false,
    toneMapped: false,
    uniforms: {
      uScene: { value: target.texture },
      uSampleSize: { value: new Vector2(1, 1) },
      uLevels: { value: finish.levels },
      uDither: { value: finish.dither },
    },
    vertexShader: /* glsl */`
      varying vec2 vPixelUv;
      void main() {
        vPixelUv = uv;
        gl_Position = vec4(position.xy, 0.0, 1.0);
      }
    `,
    fragmentShader: /* glsl */`
      uniform sampler2D uScene;
      uniform vec2 uSampleSize;
      uniform float uLevels;
      uniform float uDither;
      varying vec2 vPixelUv;
      float bayer2(vec2 p) {
        vec2 b = mod(p, 2.0);
        return mod(2.0 * b.x + 3.0 * b.y, 4.0);
      }
      void main() {
        vec2 cell = clamp(floor(vPixelUv * uSampleSize), vec2(0.0), uSampleSize - 1.0);
        vec2 centerUv = (cell + 0.5) / uSampleSize;
        vec3 linearColor = texture2D(uScene, centerUv).rgb;
        vec3 displayColor = linearToOutputTexel(vec4(linearColor, 1.0)).rgb;
        if (uLevels > 1.0) {
          float threshold = (4.0 * bayer2(cell) + bayer2(floor(cell / 2.0)) + 0.5) / 16.0 - 0.5;
          float steps = uLevels - 1.0;
          displayColor = floor(clamp(displayColor + threshold * uDither / steps, 0.0, 1.0) * steps + 0.5) / steps;
        }
        gl_FragColor = vec4(displayColor, 1.0);
      }
    `,
  });
  const outputScene = new Scene();
  const camera = new OrthographicCamera(-1, 1, 1, -1, 0, 1);
  const mesh = new Mesh(geometry, material);
  mesh.frustumCulled = false;
  outputScene.add(mesh);
  let disposed = false;
  let allocations = 0;

  function releaseGpuResources() {
    target.dispose();
    geometry.dispose();
    material.dispose();
  }

  return {
    releaseGpuResources,
    resize(outputWidth: number, outputHeight: number) {
      const scale = Math.min(1, options.resolution / Math.max(outputWidth, outputHeight));
      const width = Math.max(1, Math.round(outputWidth * scale));
      const height = Math.max(1, Math.round(outputHeight * scale));
      if (width !== target.width || height !== target.height) {
        target.setSize(width, height);
        material.uniforms.uSampleSize!.value.set(width, height);
        allocations++;
      }
    },
    render(scene: Scene, sceneCamera: Camera) {
      renderer.setRenderTarget(target);
      renderer.render(scene, sceneCamera);
      renderer.setRenderTarget(null);
      renderer.render(outputScene, camera);
    },
    getInfo() {
      return {
        sampleWidth: target.width, sampleHeight: target.height,
        designResolution: options.resolution, finish: options.finish,
        storage: halfFloat ? 'linear-half-float' : 'srgb8',
        minFilter: 'nearest', magFilter: 'nearest', mipmaps: false,
        levels: finish.levels, dither: finish.dither, allocations,
      };
    },
    dispose() {
      if (disposed) return;
      disposed = true;
      releaseGpuResources();
      outputScene.clear();
    },
  };
}

src/scene/createBlockout.ts.content:
import {
  CircleGeometry,
  ExtrudeGeometry,
  Group,
  Mesh,
  Path,
  Shape,
} from 'three';
import type { BufferGeometry } from 'three';
import { layoutConfig } from '../config/layout';
import { stoneConfig } from '../config/stone';
import { applyStoneTint, createStoneBlockGeometry, createStonePrismGeometry } from '../geometry/createStoneBlockGeometry';
import type { StoneGeometryOptions } from '../geometry/createStoneBlockGeometry';
import { createStoneMaterial } from '../materials/createStoneMaterial';
import { createWaterMaterial } from '../materials/createWaterMaterial';
import type { WaterState } from '../materials/createWaterMaterial';

/** Approved composition with shared, deterministic low-poly stone details. */
export function createBlockout(waterState?: WaterState) {
  const root = new Group();
  root.name = 'courtyard-blockout';
  const geometries = new Set<BufferGeometry>();
  function own<T extends BufferGeometry>(geometry: T): T {
    geometries.add(geometry);
    return geometry;
  }

  const blockGeometries = new Map<string, BufferGeometry>();
  const stoneMaterial = createStoneMaterial();
  const waterMaterial = createWaterMaterial(waterState);

  function box(parent: Group, name: string, width: number, height: number, depth: number, bottom: number, x = 0, z = 0, options: Partial<StoneGeometryOptions> = {}) {
    const style = { bevel: stoneConfig.bevel, cornerCut: stoneConfig.cornerCut, seed: 11, ...options };
    const key = JSON.stringify([width, height, depth, style]);
    let geometry = blockGeometries.get(key);
    if (!geometry) {
      geometry = own(createStoneBlockGeometry(width, height, depth, style));
      blockGeometries.set(key, geometry);
    }
    const mesh = new Mesh(geometry, stoneMaterial);
    mesh.name = name;
    mesh.position.set(x, bottom + height / 2, z);
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    parent.add(mesh);
    return mesh;
  }

  const f = layoutConfig.fountain;
  const fountain = new Group();
  fountain.name = 'fountain';
  fountain.position.set(...f.position);
  fountain.rotation.y = f.rotationY;
  root.add(fountain);

  const base = new Mesh(
    own(createStonePrismGeometry(
      Array.from({ length: 8 }, (_, i): [number, number] => [Math.cos(i * Math.PI / 4) * f.baseRadius, -Math.sin(i * Math.PI / 4) * f.baseRadius]),
      f.baseHeight,
      { bevel: 0.018, cornerCut: 0.025, seed: 11 },
    )),
    stoneMaterial,
  );
  base.name = 'fountain-base';
  base.position.y = f.baseHeight / 2;
  base.castShadow = true;
  base.receiveShadow = true;
  fountain.add(base);

  // An actual hole leaves the lower water plane and inner wall visible.
  const outline = new Shape();
  const hole = new Path();
  for (let i = 0; i < 8; i++) {
    const angle = i * Math.PI / 4;
    const innerAngle = -angle;
    const x = Math.cos(angle) * f.outerRadius;
    const y = Math.sin(angle) * f.outerRadius;
    const innerX = Math.cos(innerAngle) * f.innerRadius;
    const innerY = Math.sin(innerAngle) * f.innerRadius;
    if (i === 0) {
      outline.moveTo(x, y);
      hole.moveTo(innerX, innerY);
    } else {
      outline.lineTo(x, y);
      hole.lineTo(innerX, innerY);
    }
  }
  outline.closePath();
  hole.closePath();
  outline.holes.push(hole);
  const rim = new Group();
  rim.name = 'fountain-rim';
  rim.position.y = f.baseHeight;
  fountain.add(rim);
  const coping = stoneConfig.fountain;
  const coreHeight = f.rimHeight - coping.copingHeight;
  // The continuous wall reaches above the water; coping joints cannot leak through it.
  const core = new Mesh(
    own(applyStoneTint(new ExtrudeGeometry(outline, { depth: coreHeight, bevelEnabled: false, steps: 1, curveSegments: 1 }), 11)),
    stoneMaterial,
  );
  core.name = 'fountain-rim-wall';
  core.rotation.x = -Math.PI / 2;
  core.castShadow = true;
  core.receiveShadow = true;
  rim.add(core);

  function trimmedEdge(radius: number): [[number, number], [number, number]] {
    const endX = Math.cos(Math.PI / 4) * radius;
    const endZ = -Math.sin(Math.PI / 4) * radius;
    const t = coping.jointWidth / (2 * Math.hypot(endX - radius, endZ));
    return [[radius + (endX - radius) * t, endZ * t], [endX + (radius - endX) * t, endZ * (1 - t)]];
  }
  const [outerA, outerB] = trimmedEdge(f.outerRadius);
  const [innerA, innerB] = trimmedEdge(f.innerRadius);
  const copingGeometries = new Map<string, BufferGeometry>();
  for (let i = 0; i < 8; i++) {
    const chipped = coping.chippedSegments.some(index => index === i);
    const variant = chipped ? `chip-${i % 2}` : `plain-${i % 2}`;
    let geometry = copingGeometries.get(variant);
    if (!geometry) {
      geometry = own(createStonePrismGeometry([outerA, outerB, innerB, innerA], coping.copingHeight, {
        bevel: coping.bevel,
        cornerCut: 0.025,
        seed: 29 + i % 2,
        chipSize: chipped ? coping.chipSize : 0,
        chipCorner: i % 2,
      }));
      copingGeometries.set(variant, geometry);
    }
    const segment = new Mesh(geometry, stoneMaterial);
    segment.name = `fountain-coping-${i}`;
    segment.position.y = coreHeight + coping.copingHeight / 2;
    segment.rotation.y = i * Math.PI / 4;
    segment.castShadow = true;
    segment.receiveShadow = true;
    rim.add(segment);
  }

  const water = new Mesh(own(new CircleGeometry(f.innerRadius - 0.008, 8)), waterMaterial);
  water.name = 'fountain-water';
  water.rotation.x = -Math.PI / 2;
  water.position.y = f.waterHeight;
  water.receiveShadow = true;
  fountain.add(water);

  box(fountain, 'fountain-pedestal-foot', f.pedestalFootSize, f.pedestalFootHeight, f.pedestalFootSize, f.baseHeight);
  const pedestalBottom = f.baseHeight + f.pedestalFootHeight;
  box(fountain, 'fountain-pedestal', f.pedestalSize, f.pedestalHeight, f.pedestalSize, pedestalBottom);
  box(fountain, 'fountain-pedestal-cap', f.pedestalCapSize, f.pedestalCapHeight, f.pedestalCapSize, pedestalBottom + f.pedestalHeight,
    0, 0, { bevel: 0.016, chipSize: 0.06, chipCorner: 2, seed: 29 });

  const c = layoutConfig.columnShape;
  for (const [columnIndex, placement] of layoutConfig.columns.entries()) {
    const column = new Group();
    column.name = placement.name;
    const [x, y, z] = placement.position;
    column.position.set(x, y, z);
    column.rotation.y = placement.rotationY;
    const detail = stoneConfig.column;
    const profile = detail.profiles[columnIndex]!;
    box(column, `${placement.name}-base`, c.baseWidth, c.baseHeight, c.baseDepth, 0, 0, 0,
      { bevel: detail.baseBevel, chipSize: 0.04, chipCorner: columnIndex % 2, seed: 29 });
    const shaft = new Group();
    shaft.name = `${placement.name}-shaft`;
    column.add(shaft);
    const joint = stoneConfig.joints.width;
    const ratios = detail.layerRatios;
    const usableHeight = c.shaftHeight - joint * (ratios.length - 1);
    const ratioSum = ratios.reduce((sum, value) => sum + value, 0);
    let bottom = c.baseHeight;
    for (let layer = 0; layer < ratios.length; layer++) {
      const height = usableHeight * ratios[layer]! / ratioSum;
      const variant = profile.layers[layer]!;
      box(shaft, `${placement.name}-block-${layer}`, c.shaftWidth, height, c.shaftDepth, bottom,
        profile.offsets[layer]!, 0,
        { seed: detail.layerSeeds[variant]!, chipSize: detail.layerChips[variant]!, chipCorner: variant });
      bottom += height;
      if (layer < ratios.length - 1) {
        box(shaft, `${placement.name}-joint-${layer}`, c.shaftWidth - stoneConfig.joints.recess * 2, joint,
          c.shaftDepth - stoneConfig.joints.recess * 2, bottom, 0, 0,
          { bevel: 0, cornerCut: 0, seed: 47 });
        bottom += joint;
      }
    }
    box(column, `${placement.name}-cap`, c.capWidth, c.capHeight, c.capDepth, c.baseHeight + c.shaftHeight,
      0, 0, { bevel: detail.capBevel, chipSize: profile.capChip, chipCorner: profile.capCorner, seed: 47 + columnIndex });
    root.add(column);
  }

  const w = layoutConfig.wall;
  const wall = new Group();
  wall.name = 'wallLeft';
  wall.position.set(...w.position);
  wall.rotation.y = w.rotationY;
  box(wall, 'wallLeft-base', w.length + w.endSize, w.baseHeight, w.baseDepth, 0);
  const body = new Group();
  body.name = 'wallLeft-body';
  wall.add(body);
  const bodyCount = stoneConfig.wall.bodyBlocks;
  const joint = stoneConfig.joints.width;
  const bodyWidth = (w.length - (bodyCount - 1) * joint) / bodyCount;
  for (let i = 0; i < bodyCount; i++) {
    const x = -w.length / 2 + bodyWidth / 2 + i * (bodyWidth + joint);
    box(body, `wallLeft-body-${i}`, bodyWidth, w.height, w.depth, w.baseHeight, x, 0,
      { seed: 11 + i * 18, chipSize: i === bodyCount - 1 ? 0.075 : 0, chipCorner: 2 });
    if (i < bodyCount - 1) {
      box(body, `wallLeft-body-joint-${i}`, joint, w.height, w.depth - stoneConfig.joints.recess * 2,
        w.baseHeight, x + bodyWidth / 2 + joint / 2, 0, { bevel: 0, cornerCut: 0, seed: 47 });
    }
  }
  const cap = new Group();
  cap.name = 'wallLeft-cap';
  wall.add(cap);
  const capCount = stoneConfig.wall.capBlocks;
  const capWidth = (w.length - (capCount - 1) * joint) / capCount;
  for (let i = 0; i < capCount; i++) {
    const x = -w.length / 2 + capWidth / 2 + i * (capWidth + joint);
    box(cap, `wallLeft-cap-${i}`, capWidth, w.capHeight, w.capDepth, w.baseHeight + w.height, x, 0,
      { bevel: 0.018, seed: 29 + i * 18, chipSize: i === capCount - 1 ? 0.065 : 0, chipCorner: 2 });
    if (i < capCount - 1) {
      box(cap, `wallLeft-cap-joint-${i}`, joint, w.capHeight * 0.65, w.capDepth - stoneConfig.joints.recess * 2,
        w.baseHeight + w.height, x + capWidth / 2 + joint / 2, 0, { bevel: 0, cornerCut: 0, seed: 47 });
    }
  }
  box(wall, 'wallLeft-end', w.endSize, w.endHeight, w.endSize, w.baseHeight, w.length / 2, 0,
    { chipSize: 0.095, chipCorner: 2, seed: 29 });
  root.add(wall);

  const p = layoutConfig.path;
  const path = new Group();
  path.name = 'pathRight';
  path.position.set(...p.position);
  path.rotation.y = p.rotationY;
  for (let row = 0; row < p.rows; row++) {
    for (let col = 0; col < p.columns; col++) {
      box(
        path,
        `pathRight-slab-${row}-${col}`,
        p.slabWidth, p.slabHeight, p.slabDepth, 0,
        (col - (p.columns - 1) / 2) * p.stepX,
        (row - (p.rows - 1) / 2) * p.stepZ,
        {
          bevel: stoneConfig.path.bevel,
          cornerCut: stoneConfig.path.cornerCut,
          seed: 11 + (row * p.columns + col) % 3 * 18,
          chipSize: stoneConfig.path.chippedSlabs.some(index => index === row * p.columns + col) ? stoneConfig.path.chipSize : 0,
          chipCorner: (row * p.columns + col) % 4,
        },
      );
    }
  }
  root.add(path);

  let disposed = false;
  return {
    root,
    dispose() {
      if (disposed) return;
      disposed = true;
      root.removeFromParent();
      root.clear();
      for (const geometry of geometries) geometry.dispose();
      stoneMaterial.dispose();
      waterMaterial.dispose();
    },
  };
}

src/scene/createFountainEffects.ts.content:
import { Box3, CylinderGeometry, Group, InstancedMesh, Matrix4, Mesh, OctahedronGeometry, Quaternion, Sphere, SphereGeometry, Vector3 } from 'three';
import { layoutConfig } from '../config/layout';
import { waterConfig } from '../config/water';
import { createWaterMaterial } from '../materials/createWaterMaterial';
import type { WaterState } from '../materials/createWaterMaterial';

export interface DropParameters {
  phase: number;
  vx: number;
  vz: number;
  vy: number;
  radius: number;
  impactTime: number;
  impactX: number;
  impactZ: number;
  strength: number;
}

export function createDropParameters(): DropParameters[] {
  let seed: number = waterConfig.seed;
  function random() {
    seed += 0x6D2B79F5;
    let value = Math.imul(seed ^ seed >>> 15, 1 | seed);
    value ^= value + Math.imul(value ^ value >>> 7, 61 | value);
    return ((value ^ value >>> 14) >>> 0) / 4294967296;
  }
  const d = waterConfig.drops;
  return Array.from({ length: d.capacity }, (_, i) => {
    const angle = i * 2.399963229728653 + random() * 0.15;
    const speed = d.minHorizontalSpeed + random() * (d.maxHorizontalSpeed - d.minHorizontalSpeed);
    const vy = d.minVerticalSpeed + random() * (d.maxVerticalSpeed - d.minVerticalSpeed);
    const radius = d.minRadius + random() * (d.maxRadius - d.minRadius);
    const vx = Math.cos(angle) * speed, vz = Math.sin(angle) * speed;
    const fall = waterConfig.jet.emitterHeight - layoutConfig.fountain.waterHeight - radius;
    const impactTime = (vy + Math.sqrt(vy * vy + 2 * d.gravity * fall)) / d.gravity;
    return { phase: i * d.period / d.capacity, vx, vz, vy, radius, impactTime,
      impactX: vx * impactTime, impactZ: vz * impactTime, strength: 0.7 + random() * 0.3 };
  });
}

export function sampleDrop(drop: DropParameters, age: number, out: Vector3) {
  return out.set(drop.vx * age,
    waterConfig.jet.emitterHeight + drop.vy * age - 0.5 * waterConfig.drops.gravity * age * age,
    drop.vz * age);
}

export function createFountainEffects(state: WaterState) {
  const root = new Group();
  root.name = 'fountain-effects';
  const f = layoutConfig.fountain;
  root.position.set(...f.position);
  root.rotation.y = f.rotationY;
  const drops = createDropParameters();
  root.userData.dropParameters = drops;
  const material = createWaterMaterial(state, 'jet');
  const capTop = f.baseHeight + f.pedestalFootHeight + f.pedestalHeight + f.pedestalCapHeight;
  const stemHeight = waterConfig.jet.emitterHeight - capTop;
  const stemGeometry = new CylinderGeometry(waterConfig.jet.stemRadius, waterConfig.jet.stemRadius, stemHeight, 8);
  const bulbGeometry = new SphereGeometry(1, 8, 5);
  const dropGeometry = new OctahedronGeometry(1, 0);
  const stem = new Mesh(stemGeometry, material);
  stem.name = 'fountain-water-column';
  stem.position.y = capTop + stemHeight / 2;
  stem.receiveShadow = true;
  const bulb = new Mesh(bulbGeometry, material);
  bulb.name = 'fountain-water-crown';
  bulb.position.y = waterConfig.jet.emitterHeight;
  bulb.receiveShadow = true;
  const particles = new InstancedMesh(dropGeometry, material, drops.length);
  particles.name = 'fountain-water-drops';
  particles.receiveShadow = true;
  particles.boundingBox = new Box3(new Vector3(-1.4, 0.3, -1.4), new Vector3(1.4, 1.45, 1.4));
  particles.boundingSphere = particles.boundingBox.getBoundingSphere(new Sphere());
  root.add(stem, bulb, particles);
  root.visible = waterConfig.enabled;

  const position = new Vector3(), scale = new Vector3(), matrix = new Matrix4(), rotation = new Quaternion();
  const inactiveMatrix = new Matrix4();
  const events = drops.map(drop => ({ drop, age: 0 }));
  const youngestFirst = (a: typeof events[number], b: typeof events[number]) => a.age - b.age;
  const modulo = (value: number, period: number) => (value % period + period) % period;
  function update(time: number) {
    state.time.value = time;
    let active = 0;
    for (const drop of drops) {
      const age = modulo(time - drop.phase, waterConfig.drops.period);
      if (age >= drop.impactTime) continue;
      sampleDrop(drop, age, position);
      const fadeIn = Math.min(1, age / 0.07);
      const fadeOut = Math.min(1, (drop.impactTime - age) / 0.055);
      const size = drop.radius * Math.min(fadeIn, fadeOut);
      if (size < 0.0005) continue;
      scale.setScalar(size);
      matrix.compose(position, rotation, scale);
      particles.setMatrixAt(active++, matrix);
    }
    particles.count = active;
    for (let i = active; i < drops.length; i++) particles.setMatrixAt(i, inactiveMatrix);
    particles.instanceMatrix.needsUpdate = true;
    for (const event of events) event.age = modulo(time - event.drop.phase - event.drop.impactTime, waterConfig.drops.period);
    events.sort(youngestFirst);
    let rippleCount = 0;
    for (let i = 0; i < state.impacts.value.length; i++) {
      const event = events[i]!;
      if (event.age < waterConfig.ripples.lifetime) {
        state.impacts.value[i]!.set(event.drop.impactX, event.drop.impactZ, event.age, event.drop.strength);
        rippleCount++;
      } else state.impacts.value[i]!.set(0, 0, 0, 0);
    }
    const pulse = waterConfig.jet.pulse;
    const radius = waterConfig.jet.radius;
    bulb.scale.set(radius * (1 + pulse * Math.sin(time * 2.1)), radius * 0.9 * (1 + pulse * Math.sin(time * 2.8)), radius * (1 + pulse * Math.cos(time * 2.1)));
    stem.scale.set(1 + pulse * Math.sin(time * 2.1), 1, 1 + pulse * Math.sin(time * 2.1));
    root.userData.time = time;
    root.userData.activeDrops = active;
    root.userData.activeRipples = rippleCount;
  }
  update(waterConfig.initialTime);
  let disposed = false;
  return {
    root,
    update,
    dispose() {
      if (disposed) return;
      disposed = true;
      particles.dispose();
      stemGeometry.dispose(); bulbGeometry.dispose(); dropGeometry.dispose(); material.dispose();
      root.removeFromParent();root.clear();
    },
  };
}

src/scene/createScene.ts.content:
import {
  Color,
  DirectionalLight,
  HemisphereLight,
  Mesh,
  OrthographicCamera,
  PlaneGeometry,
  Scene,
} from 'three';
import { palette } from '../config/palette';
import { sceneConfig } from '../config/scene';
import { lightingConfig } from '../config/lighting';
import { createGroundMaterial } from '../materials/createGroundMaterial';
import { createBlockout } from './createBlockout';
import { createVegetation } from './createVegetation';
import { createWaterState } from '../materials/createWaterMaterial';
import { createFountainEffects } from './createFountainEffects';
import { createEnvironmentState } from '../animation/environmentMotion';
import type { EnvironmentOptions } from '../config/environment';
import { createFloatingPetals } from './createFloatingPetals';

export function createScene(options: Partial<EnvironmentOptions> = {}) {
  const environmentState = createEnvironmentState(options);
  const scene = new Scene();
  scene.background = new Color(palette.grassBase);

  const camera = new OrthographicCamera();
  camera.position.set(...sceneConfig.camera.position);
  camera.lookAt(...sceneConfig.camera.target);
  camera.near = sceneConfig.camera.near;
  camera.far = sceneConfig.camera.far;

  const groundGeometry = new PlaneGeometry(sceneConfig.ground.size, sceneConfig.ground.size);
  const groundMaterial = createGroundMaterial(environmentState);
  const ground = new Mesh(groundGeometry, groundMaterial);
  ground.name = 'courtyard-ground';
  ground.rotation.x = -Math.PI / 2;
  ground.receiveShadow = true;
  scene.add(ground);

  const waterState = createWaterState();
  const blockout = createBlockout(waterState);
  scene.add(blockout.root);
  const fountainEffects = createFountainEffects(waterState);
  scene.add(fountainEffects.root);

  const hemisphere = new HemisphereLight(
    palette.highlight,
    palette.stoneShade,
    lightingConfig.fill.intensity,
  );
  hemisphere.name = 'courtyard-fill';
  const sun = new DirectionalLight(palette.highlight, lightingConfig.sun.intensity);
  sun.name = 'courtyard-sun';
  sun.position.set(...lightingConfig.sun.position);
  sun.castShadow = lightingConfig.shadows.enabled;
  const shadows = lightingConfig.shadows;
  sun.shadow.mapSize.setScalar(shadows.mapSize);
  sun.shadow.camera.left = -shadows.extent;
  sun.shadow.camera.right = shadows.extent;
  sun.shadow.camera.top = shadows.extent;
  sun.shadow.camera.bottom = -shadows.extent;
  sun.shadow.camera.near = shadows.near;
  sun.shadow.camera.far = shadows.far;
  sun.shadow.bias = shadows.bias;
  sun.shadow.normalBias = shadows.normalBias;
  sun.shadow.radius = shadows.radius;
  scene.add(hemisphere, sun, sun.target);

  function setAspect(aspect: number) {
    const halfHeight = sceneConfig.camera.viewHeight / 2;
    camera.left = -halfHeight * aspect;
    camera.right = halfHeight * aspect;
    camera.top = halfHeight;
    camera.bottom = -halfHeight;
    camera.updateProjectionMatrix();
  }

  setAspect(1);
  camera.updateMatrixWorld(true);
  const vegetation = createVegetation(camera, environmentState);
  scene.add(vegetation.root);
  const petals = environmentState.options.enabled && environmentState.options.petals ? createFloatingPetals() : undefined;
  if (petals) { petals.update(environmentState.time.value);scene.add(petals.mesh); }
  let disposed = false;

  return {
    scene,
    camera,
    setAspect,
    update(time: number) {
      fountainEffects.update(time);
      environmentState.time.value = time;
      petals?.update(time);
    },
    waterState,
    environmentState,
    dispose() {
      if (disposed) return;
      disposed = true;
      groundGeometry.dispose();
      groundMaterial.dispose();
      blockout.dispose();
      vegetation.dispose();
      fountainEffects.dispose();
      petals?.dispose();
      sun.shadow.dispose();
      scene.clear();
    },
  };
}

src/scene/createVegetation.ts.content:
import { Color, Group, InstancedBufferAttribute, InstancedMesh, Matrix4, Quaternion, Vector3 } from 'three';
import type { BufferGeometry, Material, OrthographicCamera } from 'three';
import { layoutConfig } from '../config/layout';
import { vegetationConfig as config } from '../config/vegetation';
import { palette } from '../config/palette';
import { createFlowerGeometry, createGrassGeometry, createStemGeometry } from '../geometry/createFlowerGeometry';
import { createVegetationMaterial } from '../materials/createVegetationMaterial';
import { environmentConfig } from '../config/environment';
import { plantWindPhase } from '../animation/environmentMotion';
import type { EnvironmentState } from '../animation/environmentMotion';

interface Plant {
  x: number;
  z: number;
  height: number;
  diameter: number;
  rotation: number;
  color: number;
  radius: number;
  gap: boolean;
}

/** Conservative footprint clearance includes the plant's maximum horizontal extent. */
export function isPlantPositionClear(x: number, z: number, radius: number, margin = 0.035) {
  const f = layoutConfig.fountain;
  const c = Math.cos(f.rotationY), s = Math.sin(f.rotationY);
  const dx = x - f.position[0], dz = z - f.position[2];
  const fx = c * dx - s * dz, fz = s * dx + c * dz;
  let inPool = true;
  for (let i = 0; i < 8; i++) {
    const angle = (i + 0.5) * Math.PI / 4;
    if (fx * Math.cos(angle) - fz * Math.sin(angle) > f.baseRadius * Math.cos(Math.PI / 8) + radius + margin) inPool = false;
  }
  if (inPool) return false;

  function inRectangle(px: number, pz: number, cx: number, cz: number, width: number, depth: number, rotation: number) {
    const c = Math.cos(rotation), s = Math.sin(rotation);
    const dx = px - cx, dz = pz - cz;
    return Math.abs(c * dx - s * dz) < width / 2 + radius + margin
      && Math.abs(s * dx + c * dz) < depth / 2 + radius + margin;
  }
  const shape = layoutConfig.columnShape;
  for (const column of layoutConfig.columns) {
    if (inRectangle(x, z, column.position[0], column.position[2], shape.baseWidth, shape.baseDepth, column.rotationY)) return false;
  }
  const wall = layoutConfig.wall;
  if (inRectangle(x, z, wall.position[0], wall.position[2], wall.length + wall.endSize, Math.max(wall.baseDepth, wall.endSize), wall.rotationY)) return false;
  const p = layoutConfig.path;
  for (let row = 0; row < p.rows; row++) for (let col = 0; col < p.columns; col++) {
    const ox = (col - (p.columns - 1) / 2) * p.stepX;
    const oz = (row - (p.rows - 1) / 2) * p.stepZ;
    if (inRectangle(x, z,
      p.position[0] + Math.cos(p.rotationY) * ox + Math.sin(p.rotationY) * oz,
      p.position[2] - Math.sin(p.rotationY) * ox + Math.cos(p.rotationY) * oz,
      p.slabWidth, p.slabDepth, p.rotationY)) return false;
  }
  return true;
}

export function createVegetation(camera: OrthographicCamera, environment?: EnvironmentState) {
  const root = new Group();
  root.name = 'courtyard-vegetation';
  let seed: number = config.seed;
  function random() {
    seed += 0x6D2B79F5;
    let value = Math.imul(seed ^ seed >>> 15, 1 | seed);
    value ^= value + Math.imul(value ^ value >>> 7, 61 | value);
    return ((value ^ value >>> 14) >>> 0) / 4294967296;
  }
  const lerp = (a: number, b: number) => a + (b - a) * random();
  function visible(x: number, z: number) {
    const p = new Vector3(x, 0, z).project(camera);
    return Math.abs(p.x) < 0.98 && Math.abs(p.y) < 0.98;
  }
  function quiet(x: number, z: number) {
    const g = config.ground;
    return Math.hypot((x - g.quietCenter[0]) / g.quietRadius[0], (z - g.quietCenter[1]) / g.quietRadius[1]) < 1;
  }
  const grass: Plant[] = [], flowers: Plant[] = [];
  if (config.enabled) {
    for (let attempt = 0; grass.length < config.grass.count && attempt < config.grass.count * 120; attempt++) {
      let x: number, z: number;
      if (random() < 0.48) {
        const cluster = config.flowers.clusters[Math.floor(random() * config.flowers.clusters.length)]!;
        const angle = random() * Math.PI * 2, r = Math.sqrt(random()) * (cluster.radius + 0.5);
        x = cluster.center[0] + Math.cos(angle) * r;
        z = cluster.center[1] + Math.sin(angle) * r;
      } else { x = lerp(-7.5, 7.4); z = lerp(-8.7, 8.4); }
      if (!visible(x, z) || !isPlantPositionClear(x, z, config.grass.clearance) || (quiet(x, z) && random() < 0.9)) continue;
      grass.push({ x, z, height: lerp(config.grass.minHeight, config.grass.maxHeight), diameter: 0, rotation: random() * Math.PI * 2, color: random(), radius: config.grass.clearance, gap: false });
    }
    for (let attempt = 0; flowers.length < config.flowers.count && attempt < config.flowers.count * 120; attempt++) {
      const cluster = config.flowers.clusters[Math.floor(random() * config.flowers.clusters.length)]!;
      const angle = random() * Math.PI * 2, r = Math.pow(random(), 0.65) * cluster.radius;
      const x = cluster.center[0] + Math.cos(angle) * r, z = cluster.center[1] + Math.sin(angle) * r;
      const diameter = lerp(config.flowers.minDiameter, config.flowers.maxDiameter);
      const radius = diameter * 0.55 + 0.01;
      if (!visible(x, z) || quiet(x, z) || !isPlantPositionClear(x, z, radius)) continue;
      if (flowers.some(p => Math.hypot(p.x - x, p.z - z) < (p.radius + radius) * 0.85)) continue;
      flowers.push({ x, z, height: lerp(config.flowers.minHeight, config.flowers.maxHeight), diameter, rotation: random() * Math.PI * 2, color: random(), radius, gap: false });
    }
    if (grass.length !== config.grass.count || flowers.length !== config.flowers.count) throw new Error('Vegetation regions cannot fit the requested counts.');

    const p = layoutConfig.path;
    const gaps: [number, number][] = [];
    for (let row = 0; row < p.rows; row++) for (let col = 0; col < p.columns - 1; col++) {
      gaps.push([(col - (p.columns - 2) / 2) * p.stepX, (row - (p.rows - 1) / 2) * p.stepZ]);
    }
    for (let col = 0; col < p.columns; col++) gaps.push([(col - (p.columns - 1) / 2) * p.stepX, 0]);
    gaps.push([-p.stepX, 0], [p.stepX, 0]);
    for (const [gx, gz] of gaps.slice(0, config.grass.gapCount)) {
      const x = p.position[0] + Math.cos(p.rotationY) * gx + Math.sin(p.rotationY) * gz + lerp(-0.006, 0.006);
      const z = p.position[2] - Math.sin(p.rotationY) * gx + Math.cos(p.rotationY) * gz + lerp(-0.006, 0.006);
      if (!isPlantPositionClear(x, z, 0.023, 0.008)) throw new Error('Paving gap vegetation intersects stone.');
      grass.push({ x, z, height: lerp(config.grass.gapMinHeight, config.grass.gapMaxHeight), diameter: 0, rotation: random() * Math.PI * 2, color: random(), radius: 0.023, gap: true });
    }
  }

  const geometries: BufferGeometry[] = [];
  const materials: Material[] = [];
  const batches: InstancedMesh[] = [];
  if (config.enabled) {
    const green = createVegetationMaterial('foliage', environment), pink = createVegetationMaterial('flower', environment);
    materials.push(green, pink);
    const grassGeometry = createGrassGeometry(), stemGeometry = createStemGeometry();
    const flowerFour = createFlowerGeometry(4), flowerFive = createFlowerGeometry(5);
    geometries.push(grassGeometry, stemGeometry, flowerFour, flowerFive);
    function batch(name: string, geometry: BufferGeometry, material: Material, plants: Plant[], type: 'grass' | 'stem' | 'flower') {
      const mesh = new InstancedMesh(geometry, material, plants.length);
      mesh.name = name;
      mesh.castShadow = false;
      mesh.receiveShadow = true;
      const matrix = new Matrix4(), rotation = new Quaternion(), up = new Vector3(0, 1, 0);
      const baseColor = new Color(type === 'flower' ? palette.flower : type === 'stem' ? palette.plantStem : palette.grassBlade);
      const lightColor = new Color(type === 'flower' ? palette.flowerLight : palette.grassBladeLight);
      plants.forEach((p, i) => {
        rotation.setFromAxisAngle(up, p.rotation);
        const size = type === 'flower' ? p.diameter : p.height;
        const widthScale = type === 'grass' && p.gap ? config.grass.gapWidthScale : 1;
        matrix.compose(new Vector3(p.x, config.rootHeight + (type === 'flower' ? p.height : 0), p.z), rotation, new Vector3(size * widthScale, size, size * widthScale));
        mesh.setMatrixAt(i, matrix);
        mesh.setColorAt(i, baseColor.clone().lerp(lightColor, type === 'stem' ? p.color * 0.25 : type === 'flower' ? p.color * 0.6 : p.color * 0.85));
      });
      mesh.instanceMatrix.needsUpdate = true;
      if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
      if (environment?.options.enabled) {
        const roots = new Float32Array(plants.length * 3), shapes = new Float32Array(plants.length * 4);
        plants.forEach((p, i) => {
          const angle = type === 'grass' ? p.gap ? environmentConfig.wind.gapAngle : environmentConfig.wind.grassAngle : environmentConfig.wind.flowerAngle;
          roots.set([p.x, config.rootHeight, p.z], i * 3);
          shapes.set([p.height, angle, plantWindPhase(p.x, p.z), type === 'flower' ? 1 : 0], i * 4);
        });
        geometry.setAttribute('windRoot', new InstancedBufferAttribute(roots, 3));
        geometry.setAttribute('windShape', new InstancedBufferAttribute(shapes, 4));
      }
      mesh.computeBoundingBox();
      mesh.computeBoundingSphere();
      if (environment?.options.enabled) {
        // Includes arc shortening and tilted petals; computed once, never per frame.
        mesh.boundingBox!.expandByScalar(0.02);
        mesh.boundingSphere!.radius += 0.02;
      }
      mesh.userData.plants = plants;
      mesh.userData.plantType = type;
      batches.push(mesh);
      root.add(mesh);
    }
    batch('grass-clusters', grassGeometry, green, grass, 'grass');
    batch('flower-stems', stemGeometry, green, flowers, 'stem');
    batch('flowers-four-petal', flowerFour, pink, flowers.filter((_, i) => i % 2 === 0), 'flower');
    batch('flowers-five-petal', flowerFive, pink, flowers.filter((_, i) => i % 2 === 1), 'flower');
  }
  root.userData.seed = config.seed;
  root.userData.counts = { grass: grass.length, flowers: flowers.length, batches: batches.length };
  let disposed = false;
  return {
    root,
    dispose() {
      if (disposed) return;
      disposed = true;
      for (const mesh of batches) mesh.dispose();
      for (const geometry of geometries) geometry.dispose();
      for (const material of materials) material.dispose();
      root.removeFromParent();
      root.clear();
    },
  };
}

